key={(0,2):3,(1,0):2,(1,2):3,(1,3):4,(2,0):2,(2,1):1,(2,2):1,(3,0):2,(3,3):4}
out={(0,0):2,(0,1):2,(0,2):2,(1,1):1,(2,1):1,(2,2):3,(2,3):3,(3,0):4,(3,2):4}
def norm(coords):
 mnr=min(r for r,c in coords); mnc=min(c for r,c in coords); return {(r-mnr,c-mnc) for r,c in coords}
for name,fun in [('id',lambda r,c:(r,c)),('rot90',lambda r,c:(c,-r)),('rot180',lambda r,c:(-r,-c)),('rot270',lambda r,c:(-c,r)),('flipx',lambda r,c:(r,-c)),('flipy',lambda r,c:(-r,c)),('diag',lambda r,c:(c,r)),('anti',lambda r,c:(-c,-r))]:
 t=norm({fun(r,c) for r,c in key})
 print(name,t==norm(out),len(t),len(norm(out)))

def normmap(d):
 rs=[r for r,c in d]; cs=[c for r,c in d]; mr=min(rs); mc=min(cs); return {(r-mr,c-mc):v for (r,c),v in d.items()}
for name,fun in [('rot90',lambda r,c:(c,-r)),('rot270',lambda r,c:(-c,r))]:
 d=normmap({fun(r,c):v for (r,c),v in key.items()})
 print(name,d, d==out)

sh={(0,0),(1,1),(1,2),(2,0),(2,1)}
mk={(0,1),(1,1),(1,2),(2,0),(2,2)}
for name,fun in [('id',lambda r,c:(r,c)),('rot90',lambda r,c:(c,-r)),('rot180',lambda r,c:(-r,-c)),('rot270',lambda r,c:(-c,r)),('flipx',lambda r,c:(r,-c)),('flipy',lambda r,c:(-r,c)),('diag',lambda r,c:(c,r)),('anti',lambda r,c:(-c,-r))]:
 print(name,norm({fun(r,c) for r,c in mk})==norm(sh))
